export function initMotion(){const fine=window.matchMedia("(hover: hover) and (pointer: fine)").matches;const reduce=window.matchMedia("(prefers-reduced-motion: reduce)").matches;if(!fine||reduce)return;let n=0;const wrapWords=(node)=>{if(node.nodeType===3){const parts=node.textContent.split(/(\s+)/);if(parts.length===1&&!parts[0].trim())return;const frag=document.createDocumentFragment();parts.forEach((part)=>{if(!part.trim()){frag.append(part);return;}const span=document.createElement("span");span.className=n++%2?"title-part title-part--down":"title-part title-part--up";span.textContent=part;frag.append(span);});node.replaceWith(frag);return;}if(node.nodeType===1)[...node.childNodes].forEach(wrapWords);};document.querySelectorAll("h1, h2, h3").forEach((heading)=>{heading.classList.add("title-hover");wrapWords(heading);});document.body.classList.add("has-cursor");const cursor=document.createElement("div");cursor.className="cursor";cursor.setAttribute("aria-hidden","true");document.body.appendChild(cursor);const root=document.documentElement;let x=0,y=0,cx=0,cy=0;const hot=".card, .amenity, .plan, .stat, .reel, .btn, a, button";window.addEventListener("pointermove",(event)=>{x=event.clientX;y=event.clientY;root.style.setProperty("--mx",x+"px");root.style.setProperty("--my",y+"px");const el=event.target.closest(".card, .amenity, .plan, .stat, .story-panel");document.querySelectorAll("[data-tilt]").forEach((node)=>{if(node!==el){node.style.setProperty("--rx","0deg");node.style.setProperty("--ry","0deg");node.removeAttribute("data-tilt");}});if(el){const box=el.getBoundingClientRect();const px=(event.clientX-box.left)/box.width-0.5;const py=(event.clientY-box.top)/box.height-0.5;el.dataset.tilt="1";el.style.setProperty("--ry",(px*8).toFixed(2)+"deg");el.style.setProperty("--rx",(-py*8).toFixed(2)+"deg");}cursor.classList.toggle("is-hot",Boolean(event.target.closest(hot)));});const paint=()=>{cx+=(x-cx)*0.22;cy+=(y-cy)*0.22;cursor.style.transform=`translate(${cx}px, ${cy}px)`;requestAnimationFrame(paint);};paint();}
